# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('rejects a value outside a declared enum naming the property path and constraint', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'set_units',
        description: 'Choose units',
        inputSchema: {
          type: 'object',
          properties: {units: {type: 'string', enum: ['metric', 'imperial']}},
        },
      },
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const response = await registry.execute('set_units', {units: 'kelvin-secret'});

    expect({
      executorCalls,
      namesPath: response.result.includes('/units'),
      namesConstraint: response.result.includes('enum'),
      leaksValue: response.result.includes('kelvin-secret'),
    }).toEqual({executorCalls: 0, namesPath: true, namesConstraint: true, leaksValue: false});
  });

  it('passes valid input with an unlisted extra property to the executor unchanged, once', async () => {
    const registry = new ToolRegistry();
    const received: Record<string, unknown>[] = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => {
        received.push(input);
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {location: 'Paris', extra: 7});

    expect({received, result: response.result}).toEqual({
      received: [{location: 'Paris', extra: 7}],
      result: 'sunny',
    });
  });

